// Flat Rate Machine — Archive Registry dataset builder
// (Retrieval Machine Element 6, build batch E6-B1 per Dossier 06 §5
// + crosscheck-reconciliation build inputs E6-1/E6-2/E6-3;
// executed 2026-11-01).
//   node scripts/build-archive-registry.js [--out <file>]
//   node scripts/build-archive-registry.js --check
// Run from the-flat-rate-machine/. No dependencies beyond Node itself.
//
// WHAT THIS IS
// datasets-archive-registry.json: the standing registry of the
// Retrieval Machine's archives element (design: Dossier 06 §5).
// Preservation is a per-URL, per-era, per-location fact, and this
// dataset is where every preservation copy of the estate is
// recorded with the reconciliation's A5 fields (byte_size,
// doi_release_uri, local_archive_path, media_type, manifest_version,
// fixity_status in verified / mismatch / missing / superseded):
//   archive_target    — every URL the preservation program tracks,
//                       with its computed capture state.
//   capture           — every Internet Archive capture, CDX-verified
//                       live at generation (timestamp, status, CDX
//                       digest, WARC record length, byte-era), plus
//                       the captures the 2026-10-30/31 program
//                       recorded that the Archive no longer serves
//                       (recorded as missing, never silently dropped).
//   doi_deposit       — both Zenodo deposits (v1.1.0 + v1.2.0 under
//                       the concept DOI), per-file checksum state
//                       against the release's own signed index and
//                       the current signed index.
//   github_repository — both repos with their HEADs at generation.
//   local_archive     — the local BagIt 1.0 bag (RFC 8493) of the
//                       full sealed set: path, Payload-Oxum, fixity.
//   verification      — the 2026-11-01 runbook execution: the signed
//                       verification report (beside the index), its
//                       legs, its exception counts, and the sampled
//                       file x location matrix.
//   snapshot_run      — every snapshot/verification run on record,
//                       with attempted / confirmed / failed counts
//                       and failure records kept permanently.
//   gap_record        — Dossier 06's gaps A1–A6 with designed
//                       solutions and statuses.
//   channel           — the preservation channels, including the
//                       A6 designed non-actions with re-entry
//                       conditions (the map is complete, honestly).
//
// SEED: the evidence of 2026-11-01 (CDX re-verification of all 43
// recorded targets, Zenodo API records + deposit contents, GitHub
// HEADs, the regenerated local archive, the signed verification
// report) is frozen evidence, injected into this file by the batch
// assembler at a marked placeholder — never hand-edited. All dates
// in the output derive from the seed, never the wall clock, so
// --check is byte-stable.
